def _run_coverage_report(args: argparse.Namespace, parser: argparse.ArgumentParser) -> int:
    if args.reference == "-" and args.reads == "-":
        print(
            f"{parser.prog}: reference and reads cannot both be read from standard input",
            file=sys.stderr,
        )
        return 2

    ref_stream, close_ref, ref_code = _open_input(args.reference, parser)
    if ref_stream is None:
        return ref_code
    read_stream, close_reads, reads_code = _open_input(args.reads, parser)
    if read_stream is None:
        if close_ref:
            ref_stream.close()
        return reads_code

    try:
        # Read the whole reference and validate every read before any
        # output is produced: a failure never creates a partial output or
        # touches an existing output file.
        try:
            reference_records = list(read_sequences(ref_stream, format="fasta"))
        except _READ_ERRORS as exc:
            print(f"{parser.prog}: reference: {exc}", file=sys.stderr)
            return 2
        except OSError as exc:
            print(f"{parser.prog}: reference: {exc}", file=sys.stderr)
            return 1

        try:
            read_records = list(read_sequences(read_stream, format=args.reads_format))
        except _READ_ERRORS as exc:
            print(f"{parser.prog}: {exc}", file=sys.stderr)
            return 2
        except OSError as exc:
            print(f"{parser.prog}: {exc}", file=sys.stderr)
            return 1

        try:
            report = coverage_report(
                reference_records,
                read_records,
                match_score=args.match,
                mismatch_penalty=args.mismatch,
                gap_open=args.gap_open,
                gap_extend=args.gap_extend,
                min_score=args.min_score,
            )
            lines = [
                json.dumps(
                    entry.to_dict(),
                    ensure_ascii=False,
                    separators=(",", ":"),
                )
                for entry in report
            ]
        except (MappingReferenceError, SequenceValidationError, ValueError) as exc:
            print(f"{parser.prog}: {exc}", file=sys.stderr)
            return 2

        text = "".join(line + "\n" for line in lines)

        if args.output == "-":
            # Keep output byte-stable across platforms: no newline
            # translation on standard output.
            if hasattr(sys.stdout, "reconfigure"):
                sys.stdout.reconfigure(newline="")
            try:
                sys.stdout.write(text)
                sys.stdout.flush()
            except OSError as exc:
                print(f"{parser.prog}: {exc}", file=sys.stderr)
                return 1
            return 0

        output_stream, temporary_path = _open_temporary_output(
            args.output, parser, prefix=".coverage-report-"
        )
        if output_stream is None:
            return 1
        try:
            try:
                output_stream.write(text)
                output_stream.flush()
                output_stream.close()
                os.replace(temporary_path, args.output)
            except OSError as exc:
                _discard_temporary(output_stream, temporary_path)
                print(f"{parser.prog}: {exc}", file=sys.stderr)
                return 1
        finally:
            if not output_stream.closed:
                try:
                    output_stream.close()
                except OSError:
                    pass
    finally:
        if close_ref:
            ref_stream.close()
        if close_reads:
            read_stream.close()

    return 0


def _discard_temporary(stream: object, path: str) -> None:
    """Close and remove a temporary output file after a failed run."""

